head.script:
scwin.setPoint = function(grid, num, info, col) {
    var colID = grid.getColumnID(info.colIndex);
    var dataType = grid.getColumnOption(colID, "dataType");
    var e = event || window.event;
    var keyID = (e.which) ? e.which : e.keyCode;
    //var reg = /^\d*[.]\d{2}$/;
    var reg = new RegExp("^\\d*[.]\\d{" + num + "}$");
    var dom = e.target;
    var value = dom.value;
    var selectedValue = value.substring(dom.selectionStart, dom.selectionEnd)
    if (colID == col && dataType == "number") {
        if ((keyID >= 48 && keyID <= 57) || (keyID >= 96 && keyID <= 105) || (keyID == 190 || keyID == 110)) {
            if (selectedValue == "" && reg.test(value)) {
                e.returnValue = false;
            }
        }
    }
}
scwin.gridView1_oneditkeydown = function(info) {
    //setPoint(this,2,info,"col3");
    var colID = this.getColumnID(info.colIndex);
    var dataType = this.getColumnOption(colID, "dataType");
    var e = event || window.event;
    var keyID = (e.which) ? e.which : e.keyCode;
    // 수소점 2제자리 이후
    var reg = /^\d*[.]\d{2}$/;
    // 소수점체크
    var reg1 = /^\d*[.]\d*$/;
    var dom = e.target;
    var value = dom.value;
    var selectedValue = value.substring(dom.selectionStart, dom.selectionEnd)
    if (colID == "col3" && dataType == "number") {
        if ((keyID >= 48 && keyID <= 57) || (keyID >= 96 && keyID <= 105) || (keyID == 190 || keyID == 110)) {
            if (reg1.test(value)) {
                if (keyID == 46 || keyID == 190 || keyID == 110) {
                    console.log(keyID);
                    e.returnValue = false;
                }
            }
            if (selectedValue != value && reg.test(value)) {
                e.returnValue = false;
            }
        }
    }
};

scwin.checkVal = function(param_str) {
    if (!param_str) return false; 

    // 1. 콤마(,)를 모두 제거하여 순수 숫자 문자열로 변환
    var pureNumStr = param_str.toString().replace(/,/g, "");

    // 2. 정규표현식 검사
    // ^\d+ : 시작은 숫자
    // (\.\d{1,2})? : 소수점 1~2자리가 올 수도 있고 안 올 수도 있음
    // $ : 문자열 끝
    var isUpToTwoDecimal = /^\d+(\.\d{1,2})?$/.test(pureNumStr);

    if (isUpToTwoDecimal) {
        console.log("검사 통과 (ok): " + param_str);
    } else {
        console.log("검사 실패 (fail): " + param_str);
    }

    return isUpToTwoDecimal;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal(WebSquare.wUnit.getDomById('gridView1_cell_0_0').innerText)", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal(WebSquare.wUnit.getDomById('gridView1_cell_1_0').innerText)", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal(WebSquare.wUnit.getDomById('gridView1_cell_2_0').innerText)", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal(WebSquare.wUnit.getDomById('gridView1_cell_0_2').innerText)", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal(WebSquare.wUnit.getDomById('gridView1_cell_1_2').innerText)", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal(WebSquare.wUnit.getDomById('gridView1_cell_2_2').innerText)", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

